// Motion for drawings, in the browser: a new drawing settles through its takes, and a drawing can be drawn on, stroke
// by stroke, the first time it is seen. Both do nothing under prefers-reduced-motion.

const SETTLE = 60
const EASE = "cubic-bezier(0.23, 1, 0.32, 1)"

const reduced = () =>
  typeof matchMedia === "function" &&
  matchMedia("(prefers-reduced-motion: reduce)").matches

/** A new drawing settles: its takes play once, 60 ms each, then it rests on the first. */
export function settleDrawing(el: HTMLElement) {
  if (reduced()) return
  const takes = el.classList.contains("fl-takes")
    ? [el]
    : [...el.querySelectorAll<HTMLElement>(".fl-takes")]
  for (const t of takes) {
    if (t.children.length < 3) continue
    t.dataset.show = "1"
    setTimeout(() => (t.dataset.show = "2"), SETTLE)
    setTimeout(() => (t.dataset.show = "0"), SETTLE * 2)
    setTimeout(() => delete t.dataset.show, SETTLE * 3)
  }
}

/**
 * The pen draws the picture: strokes draw on in the order they were drawn, then the ink and wash fill in. Pen lines
 * keep their screen width (non-scaling strokes), so dashes are measured in screen pixels, not with pathLength.
 * Returns how long it takes, in ms.
 */
export function drawOn(
  svg: SVGSVGElement,
  { stroke = 240, total = 1100 } = {},
) {
  const lines = [...svg.querySelectorAll<SVGPathElement>(".ln")]
  const scale = svg.getScreenCTM()?.a || 1
  const gap = Math.min(18, (total - stroke) / Math.max(1, lines.length))
  // Every length first: measuring after an animate() would lay the page out again for each stroke.
  const lengths = lines.map((path) => path.getTotalLength() * scale + 2)
  lines.forEach((path, i) => {
    const len = lengths[i] as number
    const dash = `${len} ${len}`
    path.animate(
      [
        { strokeDasharray: dash, strokeDashoffset: len },
        { strokeDasharray: dash, strokeDashoffset: 0 },
      ],
      { duration: stroke, delay: i * gap, easing: EASE, fill: "backwards" },
    )
  })
  for (const el of svg.querySelectorAll(".ink, .wash, .sheet-fill"))
    el.animate([{ opacity: 0 }, { opacity: 1 }], {
      duration: 200,
      delay: lines.length * gap,
      easing: EASE,
      fill: "backwards",
    })
  svg.classList.remove("fl-unseen")
  return lines.length * gap + Math.max(stroke, 200)
}

/**
 * Draw an element's drawings on the first time it comes into view. For rare moments (a hero, an empty state, a first
 * run). A drawing drawn in the browser waits undrawn (fl-unseen) from its first paint. One the server sent is already
 * showing, and stays so if it is in view when the script arrives; one that starts out of view is hidden there, where
 * nobody sees it go, and drawn on when it comes into view. Returns a cleanup for effects.
 */
export function drawWhenSeen(el: HTMLElement) {
  const svgs = () => [...el.querySelectorAll<SVGSVGElement>("svg.fl-drawing")]
  const show = (list: SVGSVGElement[]) =>
    list.forEach((svg) => svg.classList.remove("fl-unseen"))
  if (reduced() || typeof IntersectionObserver !== "function") {
    show(svgs())
    return () => {}
  }
  let waiting = svgs().some((svg) => svg.classList.contains("fl-unseen"))
  let timer: ReturnType<typeof setTimeout> | undefined
  const observer = new IntersectionObserver(
    (entries) => {
      const seen = entries.some((e) => e.isIntersecting)
      if (!waiting) {
        // The first report says where the server's drawing is: on screen, it stays as it is.
        if (seen) return observer.disconnect()
        svgs().forEach((svg) => svg.classList.add("fl-unseen"))
        waiting = true
        return
      }
      if (!seen) return
      observer.disconnect()
      // The pen draws the take on show; the others, which line boil shows in turn, appear once it has finished.
      const [take, ...rest] = svgs()
      timer = setTimeout(() => show(rest), take ? drawOn(take) : 0)
    },
    { threshold: 0.35 },
  )
  observer.observe(el)
  return () => {
    observer.disconnect()
    clearTimeout(timer)
  }
}

// Line boil on a scene, one thing at a time. A scene groups each object it places under its key (g[data-k], in every
// take); the part under the pointer, or under a tap on a touch screen, boils while the rest of the room rests on its
// first take. Its groups from each take are copied into an SVG of their own over the room, which cycles as a whole
// element (data-hot, fl-hot and fl-part in styles/drawing.css). The part is found from its groups' boxes in the first take:
// the smallest box that holds the point, so a person in front of a counter wins over the counter. Measured once per
// drawing, at the first hover.

interface Part {
  key: string
  box: [number, number, number, number]
  area: number
}
const parts = new WeakMap<Element, Part[]>()

function partsOf(svg: SVGSVGElement) {
  const known = parts.get(svg)
  if (known) return known
  const boxes = new Map<string, [number, number, number, number]>()
  svg.querySelectorAll<SVGGElement>("g[data-k]").forEach((g) => {
    const key = g.dataset.k
    if (key === undefined) return
    const { x, y, width, height } = g.getBBox()
    const was = boxes.get(key)
    boxes.set(
      key,
      was
        ? [
            Math.min(was[0], x),
            Math.min(was[1], y),
            Math.max(was[2], x + width),
            Math.max(was[3], y + height),
          ]
        : [x, y, x + width, y + height],
    )
  })
  const list = [...boxes].map(([key, box]) => ({
    key,
    box,
    area: (box[2] - box[0]) * (box[3] - box[1]),
  }))
  parts.set(svg, list)
  return list
}

/** The key of the part of a scene's drawing at a point on screen, if any. */
export function partAt(el: HTMLElement, x: number, y: number) {
  const svg = el.firstElementChild
  if (!(svg instanceof SVGSVGElement)) return undefined
  const m = svg.getScreenCTM()
  if (!m) return undefined
  const p = new DOMPoint(x, y).matrixTransform(m.inverse())
  let best: Part | undefined
  for (const part of partsOf(svg)) {
    const [x0, y0, x1, y1] = part.box
    if (p.x < x0 || p.x > x1 || p.y < y0 || p.y > y1) continue
    if (!best || part.area < best.area) best = part
  }
  return best?.key
}

const SVG = "http://www.w3.org/2000/svg"

// Room around the part's geometry for the pen's width and its round ends, in CSS pixels: the copy clips to its box.
const PAD = 8

/**
 * The part's box on screen: its groups in every take (they wobble apart), within the room's own box. A copy as large
 * as the room would be a layer the size of the room, and each new one is rasterized whole, tiles of nothing included:
 * about 40 raster tasks at every part the pointer crosses at 2x, as heavy on a GPU as boiling inside the room was. A
 * masked group reaches as far as its mask (the whole room), so the copy clips to the box (fl-part in drawing.css).
 */
function boxOf(takes: SVGSVGElement[], groups: string) {
  const room = takes[0].getBoundingClientRect()
  let [x0, y0, x1, y1] = [Infinity, Infinity, -Infinity, -Infinity]
  for (const take of takes)
    take.querySelectorAll(groups).forEach((g) => {
      const r = g.getBoundingClientRect()
      if (!r.width && !r.height) return
      x0 = Math.min(x0, r.left)
      y0 = Math.min(y0, r.top)
      x1 = Math.max(x1, r.right)
      y1 = Math.max(y1, r.bottom)
    })
  // Kept inside the room, so a copy never stretches the grid it shares with it, and a whole number of device pixels
  // from its corner, so the copy's lines fall on the same sub-pixels as the room's rather than a pixel beside them.
  const px = devicePixelRatio || 1
  const snap = (v: number, from: number, round: (n: number) => number) =>
    from + round((v - from) * px) / px
  x0 = snap(Math.max(x0 - PAD, room.left), room.left, Math.floor)
  y0 = snap(Math.max(y0 - PAD, room.top), room.top, Math.floor)
  x1 = Math.min(
    snap(x1 + PAD, room.left, Math.ceil),
    snap(room.right, room.left, Math.floor),
  )
  y1 = Math.min(
    snap(y1 + PAD, room.top, Math.ceil),
    snap(room.bottom, room.top, Math.floor),
  )
  return x1 > x0 && y1 > y0 ? new DOMRect(x0, y0, x1 - x0, y1 - y0) : undefined
}

/** Boil one part of a scene, or none: a copy of its groups from each take, stacked over the room where the part is. */
export function setHot(el: HTMLElement, key: string | undefined) {
  const copies = el.querySelectorAll(":scope > .fl-part")
  if (el.dataset.hot === key && (key === undefined || copies.length)) return
  copies.forEach((c) => c.remove())
  el.querySelectorAll(".fl-hot").forEach((g) => g.classList.remove("fl-hot"))
  if (key === undefined) return void delete el.dataset.hot
  const takes = [...el.children].filter((c) => c instanceof SVGSVGElement)
  const groups = `g[data-k="${CSS.escape(key)}"]`
  const m = takes[0]?.getScreenCTM()
  const box = m && boxOf(takes, groups)
  if (!m || !box) return void delete el.dataset.hot
  // The copy's viewBox is the part's box in the room's own units, so its lines (and masks) land where they are drawn.
  const inv = m.inverse()
  const a = new DOMPoint(box.left, box.top).matrixTransform(inv)
  const b = new DOMPoint(box.right, box.bottom).matrixTransform(inv)
  // Screen pixels to the element's own, where an ancestor scales it (offsetWidth is rounded, so only past a pixel).
  const shown = el.getBoundingClientRect().width
  const scale =
    Math.abs(el.offsetWidth - shown) > 1 ? el.offsetWidth / shown || 1 : 1
  const made: SVGSVGElement[] = []
  takes.forEach((take, i) => {
    const copy = document.createElementNS(SVG, "svg")
    copy.setAttribute("viewBox", `${a.x} ${a.y} ${b.x - a.x} ${b.y - a.y}`)
    // Each axis to its own size: layout rounds the box a little, which "meet" would answer by centring the lines.
    copy.setAttribute("preserveAspectRatio", "none")
    copy.style.width = `${box.width * scale}px`
    copy.style.height = `${box.height * scale}px`
    made.push(copy)
    copy.setAttribute("class", "fl-drawing fl-size-own fl-part")
    copy.setAttribute("aria-hidden", "true")
    copy.dataset.take = String(i)
    // A group inside a masked layer keeps its mask (the mask stays where it is, in its take).
    take.querySelectorAll(groups).forEach((g) => {
      const mask = g.parentElement?.getAttribute("mask")
      const part = g.cloneNode(true)
      if (!mask) return void copy.append(part)
      const layer = document.createElementNS(SVG, "g")
      layer.setAttribute("mask", mask)
      layer.append(part)
      copy.append(layer)
    })
    el.append(copy)
  })
  // The copies sit at the start of the grid cell; move them over the part.
  const at = made[0].getBoundingClientRect()
  const move = `translate(${(box.left - at.left) * scale}px, ${(box.top - at.top) * scale}px)`
  made.forEach((copy) => (copy.style.transform = move))
  takes[0].querySelectorAll(groups).forEach((g) => g.classList.add("fl-hot"))
  el.dataset.hot = key
}

// Line boil's other takes, drawn in the browser where boil can show them. A server-rendered drawing carries its first
// take only, so a page ships each drawing once. boilTakes() adds the second and third once the page's boil setting
// would cycle them: during idle time for drawings in view when boil runs always, or on hover with a pointer that can
// hover (the default), and at once under the pointer. A touch screen has no hover, so there a tap draws them and boils
// the drawing once (boilOnce). Boil off or reduced motion, and they are never drawn. The pen engine loads only when
// the first one is. No React, so static pages can use it too. A scene boils only the thing under the pointer, or the
// one tapped (drawing-parts.ts), and a scene spot boils the object it stands over.
import { ownIds } from "@/fineliner/lib/own-ids"
import { partAt, setHot } from "./drawing-parts"
import type { SceneFormat, SceneName } from "@/fineliner/pen/scenes"

const TAKES = 3
const watched = new WeakSet<HTMLElement>()
const inView = new Set<HTMLElement>()
const waiting: HTMLElement[] = []
let engine: Promise<typeof import("@/fineliner/pen")> | undefined
let loadDrawings: (() => Promise<unknown>) | undefined
let drawings: Promise<unknown> | undefined
let seen: IntersectionObserver | undefined
let made = 0
let busy = false

const reduced = () => matchMedia("(prefers-reduced-motion: reduce)").matches
const running = (el: HTMLElement, name: string) =>
  getComputedStyle(el).getPropertyValue(name).trim() === "running"
const boils = (el: HTMLElement) =>
  !reduced() &&
  (running(el, "--boil") ||
    (running(el, "--boil-hover") &&
      matchMedia("(hover: hover) and (pointer: fine)").matches))
// Where boil waits for a hover, a tap on a touch screen boils the drawing once instead.
const boilsOnTap = (el: HTMLElement) =>
  !reduced() && !running(el, "--boil") && running(el, "--boil-hover")

/** Add the next take, or every missing take (`all`, under the pointer). Returns whether one is still missing. */
async function grow(el: HTMLElement, all = false) {
  const { seed, object, scene, format, hand } = el.dataset
  const has = el.children.length
  if (!seed || has >= TAKES) return false
  // A drawing still waiting to be drawn on gets its other takes afterwards, so boil never flashes them first.
  if (el.querySelector(".fl-unseen")) {
    setTimeout(() => queue(el), 1500)
    return false
  }
  const [{ drawing }] = await Promise.all([
    (engine ??= import("@/fineliner/pen")),
    (drawings ??= loadDrawings?.()),
  ])
  // A reroll may have redrawn it, takes and all, while the engine loaded.
  if (el.dataset.seed !== seed || el.children.length !== has) return false
  let takes: string[]
  try {
    takes = drawing({
      object,
      scene: scene as SceneName | undefined,
      format: format as SceneFormat | undefined,
      seed,
      hand: hand === "calm" ? "calm" : "lively",
      takes: all ? TAKES : has + 1,
      from: has,
    })
  } catch {
    return false
  }
  el.insertAdjacentHTML("beforeend", ownIds(takes.join(""), `t${++made}`))
  return el.children.length < TAKES
}

function queue(el: HTMLElement) {
  if (!waiting.includes(el)) waiting.push(el)
  if (busy) return
  busy = true
  idle(next)
}
const idle = (fn: () => void) =>
  "requestIdleCallback" in window
    ? requestIdleCallback(fn, { timeout: 2000 })
    : setTimeout(fn, 60)
// One take per idle moment, so drawing takes never holds up the page.
async function next() {
  const el = waiting.shift()
  if (el?.isConnected && inView.has(el) && boils(el) && (await grow(el)))
    waiting.push(el)
  if (waiting.length) idle(next)
  else busy = false
}

const TAP_STEPS = [1, 2, 0, 1, 2, 0]
const paceOf = (el: HTMLElement) => {
  const pace = getComputedStyle(el).getPropertyValue("--take").trim()
  return parseFloat(pace) * (/\ds$/.test(pace) ? 1000 : 1) || 120
}
/** A tap's boil: every take drawn, then two rounds of them at the boil's pace, resting on the first. */
async function boilOnce(el: HTMLElement) {
  if (el.dataset.show !== undefined) return
  el.dataset.show = "0"
  await grow(el, true)
  if (el.children.length < TAKES) return void delete el.dataset.show
  const take = paceOf(el)
  TAP_STEPS.forEach((show, i) =>
    setTimeout(() => (el.dataset.show = String(show)), take * i),
  )
  setTimeout(() => delete el.dataset.show, take * TAP_STEPS.length)
}
/** A tap on a scene boils the part tapped the same way, the rest of the room still. */
async function boilPartOnce(el: HTMLElement, key: string) {
  if (el.dataset.hot !== undefined || el.dataset.show !== undefined) return
  await grow(el, true)
  if (el.children.length < TAKES) return
  setHot(el, key)
  const done = paceOf(el) * TAP_STEPS.length
  setTimeout(() => el.dataset.hot === key && setHot(el, undefined), done)
}

// The scene under a fine pointer, and whether its parts boil there (hover boil, not always, not reduced motion).
let over: HTMLElement | undefined
let parted = false
let frame = 0
function hover(target: Element, x: number, y: number) {
  const spot = target.closest?.<HTMLElement>(
    "[data-slot=scene-spot][data-region]",
  )
  const el = spot
    ? spot
        .closest("[data-slot=scene-spots]")
        ?.querySelector<HTMLElement>(".fl-takes[data-scene]")
    : target.closest?.<HTMLElement>(".fl-takes[data-scene]")
  if (el !== over) {
    if (over && parted) setHot(over, undefined)
    over = el ?? undefined
    parted = !!el && watched.has(el) && boils(el) && !running(el, "--boil")
    if (el && parted) void grow(el, true)
  }
  if (!over || !parted || over.children.length < TAKES || over.dataset.show)
    return
  setHot(over, spot ? spot.dataset.region : partAt(over, x, y))
}

function start() {
  // A tap, not the start of a scroll: the finger lifts on the drawing it came down on (a scroll cancels the pointer).
  let tapped: HTMLElement | undefined
  document.addEventListener(
    "pointerdown",
    (e) => {
      const el =
        e.pointerType === "mouse"
          ? undefined
          : (e.target as Element).closest?.<HTMLElement>(".fl-takes")
      tapped = el && watched.has(el) ? el : undefined
    },
    { passive: true },
  )
  document.addEventListener("pointercancel", () => (tapped = undefined))
  document.addEventListener("pointerup", (e) => {
    const el = (e.target as Element).closest?.<HTMLElement>(".fl-takes")
    if (el && el === tapped && boilsOnTap(el)) {
      const key = el.dataset.scene && partAt(el, e.clientX, e.clientY)
      if (!el.dataset.scene) void boilOnce(el)
      else if (key) void boilPartOnce(el, key)
    }
    tapped = undefined
  })
  document.addEventListener(
    "pointermove",
    (e) => {
      if (e.pointerType === "touch") return
      const { target, clientX, clientY } = e
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() =>
        hover(target as Element, clientX, clientY),
      )
    },
    { passive: true },
  )
  // A hot part's copy is placed in pixels; a resize drops it and the next move places it again.
  addEventListener("resize", () => over && setHot(over, undefined), {
    passive: true,
  })
  seen = new IntersectionObserver(
    (entries) => {
      for (const e of entries) {
        const el = e.target as HTMLElement
        if (!e.isIntersecting) {
          inView.delete(el)
          continue
        }
        inView.add(el)
        queue(el)
      }
    },
    { rootMargin: "200px" },
  )
  document.addEventListener("pointerover", (e) => {
    const el = (e.target as Element).closest?.<HTMLElement>(".fl-takes")
    if (el && watched.has(el) && boils(el)) void grow(el, true)
  })
  // Boil turned on, here or for a part of the page: the drawings in view get their takes.
  new MutationObserver(() => inView.forEach(queue)).observe(
    document.documentElement,
    { attributes: true, subtree: true, attributeFilter: ["data-boil"] },
  )
}

/** Draw a drawing's other takes where boil shows them. `<Drawing>` calls it; a server-only page calls boilTakesIn(). */
export function boilTakes(el: HTMLElement) {
  if (watched.has(el) || !el.dataset.seed) return
  watched.add(el)
  if (!seen) start()
  seen?.observe(el)
}

/**
 * Every drawing under `root` that carries one take, for pages whose drawings render without React in the browser.
 * `load` registers the page's drawings once, before drawing the first take. A later loader replaces an unused one.
 * For example: `boilTakesIn(document, () => import("@/fineliner/pen/objects"))`.
 */
export function boilTakesIn(
  root: ParentNode = document,
  load?: () => Promise<unknown>,
) {
  if (load && !drawings) loadDrawings = load
  root.querySelectorAll<HTMLElement>(".fl-takes[data-seed]").forEach(boilTakes)
}

"use client"

import {
  useEffect,
  useMemo,
  useRef,
  useState,
  useSyncExternalStore,
  type ComponentProps,
} from "react"
import { drawing, type DrawingOptions } from "@/fineliner/pen"
import { cn } from "@/fineliner/lib/utils"
import { drawWhenSeen } from "./drawing-motion"
import { boilTakes } from "./drawing-takes"
import { useOwnIds } from "@/fineliner/lib/svg-ids"

export interface DrawingProps
  extends
    Omit<ComponentProps<"span">, "children" | "title">,
    Omit<DrawingOptions, "takes"> {
  /** One still drawing instead of three takes: no line boil, no settling. */
  still?: boolean
  /** Draw it on, stroke by stroke, the first time it comes into view. For rare moments: a hero, an empty state. */
  drawOnView?: boolean
}

const never = () => () => {}

/**
 * A seeded drawing from the object library, or a scene. Same seed, same drawing on the server and in the browser. Its
 * first take is named by `title` (or the object's own name), and title="" makes it decorative. Line boil cycles three
 * takes where data-boil allows: the server sends the first, and the browser draws the other two where boil can show
 * them (drawing-takes.ts); a drawing drawn in the browser, as after a reroll, has all three at once.
 */
export function Drawing({
  object,
  scene,
  format,
  seed,
  hand,
  title,
  still,
  drawOnView,
  className,
  ref: outer,
  ...props
}: DrawingProps) {
  const own = useOwnIds()
  // True on the server and while React hydrates the server's markup; false in a browser render.
  const hydrating = useSyncExternalStore(
    never,
    () => false,
    () => true,
  )
  // The server's markup is already this drawing, so hydration keeps it instead of drawing every take again (a scene
  // is a few hundred milliseconds of work on a phone). The pen draws in the browser once a prop changes.
  const asked = [
    object,
    scene,
    format,
    seed,
    hand,
    title,
    still,
    drawOnView,
  ].join("|")
  const [served] = useState(() =>
    hydrating && typeof window !== "undefined" ? asked : null,
  )
  const [moved, setMoved] = useState(false)
  if (served !== null && asked !== served && !moved) setMoved(true)
  const keep = !moved && asked === served
  const html = useMemo(() => {
    if (keep) return ""
    const svg = drawing({
      object,
      scene,
      format,
      seed,
      hand,
      title,
      takes: still || typeof window === "undefined" ? 1 : 3,
    })
    // Drawn in the browser, a drawing that is drawn on waits undrawn from its first paint. The server's copy shows at
    // once: a page never waits for its script to show its pictures (drawWhenSeen hides it only out of view).
    const waits = drawOnView && typeof window !== "undefined"
    return svg
      .map((s) =>
        waits
          ? s.replace('class="fl-drawing ', 'class="fl-drawing fl-unseen ')
          : s,
      )
      .join("")
  }, [keep, object, scene, format, seed, hand, title, still, drawOnView])
  const inner = useRef<HTMLSpanElement | null>(null)
  useEffect(() => {
    const el = inner.current
    return drawOnView && el ? drawWhenSeen(el) : undefined
  }, [drawOnView, html])
  useEffect(() => {
    if (!still && inner.current) boilTakes(inner.current)
  }, [still])
  return (
    <span
      // A caller's ref is kept beside the drawing's own, which drawOnView needs.
      ref={(el) => {
        inner.current = el
        if (typeof outer === "function") outer(el)
        else if (outer) outer.current = el
      }}
      data-slot="drawing"
      data-object={object}
      data-scene={scene}
      data-format={format}
      // What the browser needs to draw the other takes (drawing-takes.ts).
      data-seed={still ? undefined : String(seed)}
      data-hand={hand}
      className={cn("fl-takes", className)}
      // Kept markup is left as the server sent it: React does not compare inner HTML when it hydrates.
      dangerouslySetInnerHTML={{ __html: own(html) }}
      suppressHydrationWarning
      {...props}
    />
  )
}

import type { ComponentProps } from "react"
import { cn } from "@/fineliner/lib/utils"

/** The pen as typefaces: Fineliner Naïve Sans, Inline and Tramline. */
export type LetteringFace = "line" | "inline" | "tramline"

export interface LetteringProps extends Omit<
  ComponentProps<"span">,
  "children"
> {
  /** The words to letter. */
  text: string
  /**
   * "line" (the default) sets the words in Fineliner Naïve Sans. "inline" sets them in Fineliner Naïve Inline with its
   * tint in the wash under the outlines (import styles/inline.generated.css once); "tramline" in Fineliner Naïve Tramline,
   * every stroke three parallel lines (import styles/tramline.generated.css once). Size it with a text size.
   */
  face?: LetteringFace
}

const FONTS = {
  line: "font-line",
  inline: "font-inline",
  tramline: "font-tramline",
} satisfies Record<LetteringFace, string>

/**
 * Display lettering: words set in one of the pen's typefaces, whose three takes per letter rotate so a repeated letter
 * is never stamped. It is text, so search engines and screen readers read it as words. For words drawn by the pen as
 * an SVG from a seed, use lettering() from the pen engine.
 */
export function Lettering({
  text,
  face = "line",
  className,
  ...props
}: LetteringProps) {
  return (
    <span
      data-slot="lettering"
      data-face={face}
      data-text={face === "inline" ? text : undefined}
      className={cn(FONTS[face], "font-normal", className)}
      {...props}
    >
      {text}
    </span>
  )
}

import { useMemo, type ComponentProps } from "react"
import { penMark, type HandName, type MarkName } from "@/fineliner/pen"
import { cn } from "@/fineliner/lib/utils"
import { useOwnIds } from "@/fineliner/lib/svg-ids"

export interface PenMarkProps extends Omit<ComponentProps<"span">, "children"> {
  /** tick, ring, dot, underline, strike, arrow, chevron or pill. */
  name: MarkName
  seed: string | number
  hand?: HandName
}

/** One small pen mark, decorative: the element it marks carries the meaning. Size it with the span. */
export function PenMark({
  name,
  seed,
  hand,
  className,
  ...props
}: PenMarkProps) {
  const own = useOwnIds()
  const html = useMemo(() => penMark(name, seed, hand), [name, seed, hand])
  return (
    <span
      aria-hidden="true"
      data-slot="pen-mark"
      data-mark={name}
      className={cn("block [&>svg]:size-full", className)}
      dangerouslySetInnerHTML={{ __html: own(html) }}
      {...props}
    />
  )
}

/** A word or figure ringed by the pen, as a badge of note: the ring stretches to the text. */
export function Circled({
  seed,
  hand,
  className,
  children,
  ...props
}: Omit<ComponentProps<"span">, "seed"> & {
  seed: string | number
  hand?: HandName
}) {
  return (
    <span
      data-slot="circled"
      className={cn("relative inline-block px-[0.6em]", className)}
      {...props}
    >
      <PenMark
        name="ring"
        seed={seed}
        hand={hand}
        className="absolute -inset-x-[0.2em] -inset-y-[0.3em]"
      />
      {children}
    </span>
  )
}
